import torch; exec("class Solution:\n    def generate(self, model, new_chars, context, context_length, int_to_char):\n        result = []\n        for _ in range(new_chars):\n            if context.shape[1] > context_length:\n                context = context[:, -context_length:]\n            logits = model(context)\n            last_logits = logits[:, -1, :]\n            probs = torch.nn.functional.softmax(last_logits, dim=-1)\n            # FIX: generator state reset hataya - same random draw repeat ho raha tha\n            next_token = torch.multinomial(probs, 1)\n            context = torch.cat((context, next_token), dim=-1)\n            result.append(int_to_char[next_token.item()])\n        return ''.join(result)")